import random, time
n=18
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]

def shortest(adj,s,t,limit=6):
 if s==t:return 0
 seen={s}; q=[(s,0)]
 for v,d in q:
  if d>=limit: continue
  for w in adj[v]:
   if w==t: return d+1
   if w not in seen:
    seen.add(w); q.append((w,d+1))
 return 999

def three_col(edges):
 adj=[set() for _ in range(n)]
 for u,v in edges: adj[u].add(v); adj[v].add(u)
 order=sorted(range(n), key=lambda x:-len(adj[x]))
 col=[-1]*n
 def dfs(idx):
  if idx==n: return True
  v=order[idx]
  forbidden={col[w] for w in adj[v] if col[w]!=-1}
  for c in range(3):
   if c not in forbidden:
    col[v]=c
    if dfs(idx+1): return True
    col[v]=-1
  return False
 return dfs(0)

def greedy(seed):
 random.seed(seed)
 adj=[set() for _ in range(n)]
 edges=[]
 cand=all_edges[:]
 # random order weighted maybe prefer high degree regular? just shuffle; iterate until no add
 while True:
  feasible=[]
  for e in cand:
   u,v=e
   if v in adj[u]: continue
   if shortest(adj,u,v,6)>6: # no path length <=6
    feasible.append(e)
  if not feasible: break
  # choose random, maybe favor low degrees? high? 
  # among feasible, choose with min degree sum to balance
  if random.random()<0.8:
   mind=min(len(adj[u])+len(adj[v]) for u,v in feasible)
   opts=[e for e in feasible if len(adj[e[0]])+len(adj[e[1]])<=mind+random.randint(0,2)]
   e=random.choice(opts)
  else:
   e=random.choice(feasible)
  u,v=e
  edges.append(e); adj[u].add(v); adj[v].add(u)
  if len(edges)>=29:
   # check 3col
   if three_col(edges): return edges
 return edges if len(edges)>=29 and three_col(edges) else None

